def json_parse(s: str):
    # Index as a mutable object, so it can be updated in helper functions
    idx = [0]

    def skip_whitespace():
        # No whitespace per problem, but add if input might allow in extension
        while idx[0] < len(s) and s[idx[0]] == ' ':
            idx[0] += 1

    def parse_value():
        if idx[0] >= len(s):
            return None
        char = s[idx[0]]
        if char == '"':
            return parse_string()
        elif char == '{':
            return parse_object()
        elif char == '[':
            return parse_array()
        elif char == 't':
            return parse_true()
        elif char == 'f':
            return parse_false()
        elif char == 'n':
            return parse_null()
        else:
            # number: could be negative or digit
            return parse_number()

    def parse_string():
        # Assume s[idx] == '"'
        idx[0] += 1  # skip opening quote
        start = idx[0]
        while s[idx[0]] != '"':
            idx[0] += 1
        value = s[start:idx[0]]
        idx[0] += 1  # skip closing quote
        return value

    def parse_number():
        start = idx[0]
        if s[idx[0]] == '-':
            idx[0] += 1
        while idx[0] < len(s) and s[idx[0]].isdigit():
            idx[0] += 1
        is_float = False
        # Fractional part
        if idx[0] < len(s) and s[idx[0]] == '.':
            is_float = True
            idx[0] += 1
            while idx[0] < len(s) and s[idx[0]].isdigit():
                idx[0] += 1
        # Exponent part (e.g. 1e5, 2.5E-3)
        if idx[0] < len(s) and s[idx[0]] in 'eE':
            is_float = True
            idx[0] += 1
            if idx[0] < len(s) and s[idx[0]] in '+-':
                idx[0] += 1
            while idx[0] < len(s) and s[idx[0]].isdigit():
                idx[0] += 1
        text = s[start:idx[0]]
        return float(text) if is_float else int(text)

    def parse_true():
        assert s[idx[0]:idx[0]+4] == "true"
        idx[0] += 4
        return True

    def parse_false():
        assert s[idx[0]:idx[0]+5] == "false"
        idx[0] += 5
        return False

    def parse_null():
        assert s[idx[0]:idx[0]+4] == "null"
        idx[0] += 4
        return None

    def parse_array():
        arr = []
        idx[0] += 1  # skip [
        while True:
            if s[idx[0]] == ']':
                idx[0] += 1
                break
            arr.append(parse_value())
            if s[idx[0]] == ',':
                idx[0] += 1  # skip comma
            elif s[idx[0]] == ']':
                idx[0] += 1
                break
        return arr

    def parse_object():
        obj = {}
        idx[0] += 1  # skip {
        while True:
            if s[idx[0]] == '}':
                idx[0] += 1
                break
            key = parse_string()
            assert s[idx[0]] == ':'
            idx[0] += 1  # skip colon
            val = parse_value()
            obj[key] = val
            if s[idx[0]] == ',':
                idx[0] += 1  # skip comma
            elif s[idx[0]] == '}':
                idx[0] += 1
                break
        return obj

    return parse_value()
